inline uint16_t GbkLookup(uint8_t lead, uint8_t trail) {
    if (lead < 0x81 || lead > 0xFE) return 0;
    if (trail < 0x40 || trail == 0x7F || trail > 0xFE) return 0;
    uint8_t li = (uint8_t)(lead - 0x81);
    uint8_t ti = (uint8_t)(trail < 0x7F ? trail - 0x40 : trail - 0x41);
    uint16_t q = (uint16_t)(li * 256 + ti);
    int lo = 0, hi = (int)(sizeof(kGbkTable) / sizeof(kGbkTable[0]));
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        uint16_t a = (uint16_t)(kGbkTable[mid].li * 256 + kGbkTable[mid].ti);
        if (a < q) lo = mid + 1; else hi = mid;
    }
    if (lo < (int)(sizeof(kGbkTable) / sizeof(kGbkTable[0])) &&
        kGbkTable[lo].li == li && kGbkTable[lo].ti == ti) return kGbkTable[lo].cp;
    return 0;
}
